import java.util.*;
import java.security.MessageDigest;

// Tracks which chunks of a resumable upload have been received, letting a
// client resume exactly where it left off after a connection drop.
public class ChunkedUploadService {
    private final Map<String, Set<Integer>> receivedChunks = new HashMap<>();
    private final Map<String, Integer> totalChunks = new HashMap<>();

    public void startUpload(String uploadId, int chunkCount) {
        receivedChunks.put(uploadId, new HashSet<>());
        totalChunks.put(uploadId, chunkCount);
    }

    public boolean acceptChunk(String uploadId, int chunkNumber, byte[] data, String expectedChecksum) {
        String actualChecksum = computeChecksum(data);
        if (!actualChecksum.equals(expectedChecksum)) {
            return false; // caller should retry just this chunk
        }
        receivedChunks.get(uploadId).add(chunkNumber);
        return true;
    }

    public boolean isComplete(String uploadId) {
        return receivedChunks.get(uploadId).size() == totalChunks.get(uploadId);
    }

    public Set<Integer> missingChunks(String uploadId) {
        Set<Integer> missing = new HashSet<>();
        int total = totalChunks.get(uploadId);
        Set<Integer> received = receivedChunks.get(uploadId);
        for (int i = 0; i < total; i++) {
            if (!received.contains(i)) missing.add(i);
        }
        return missing;
    }

    private String computeChecksum(byte[] data) {
        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] digest = md5.digest(data);
            StringBuilder hex = new StringBuilder();
            for (byte b : digest) hex.append(String.format("%02x", b));
            return hex.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

