import hashlib

# Tracks which chunks of a resumable upload have been received, letting a
# client resume exactly where it left off after a connection drop.
class ChunkedUploadService:
    def __init__(self):
        self.received_chunks = {}
        self.total_chunks = {}

    def start_upload(self, upload_id, chunk_count):
        self.received_chunks[upload_id] = set()
        self.total_chunks[upload_id] = chunk_count

    def accept_chunk(self, upload_id, chunk_number, data, expected_checksum):
        actual_checksum = hashlib.md5(data).hexdigest()
        if actual_checksum != expected_checksum:
            return False  # caller should retry just this chunk
        self.received_chunks[upload_id].add(chunk_number)
        return True

    def is_complete(self, upload_id):
        return len(self.received_chunks[upload_id]) == self.total_chunks[upload_id]

    def missing_chunks(self, upload_id):
        total = self.total_chunks[upload_id]
        received = self.received_chunks[upload_id]
        return {i for i in range(total) if i not in received}

