import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// Buffers view increments in memory and flushes them to the database in
// batches, avoiding a write per individual view event on a viral video.
public class ViewCountAggregator {
    private final Map<String, Integer> pendingViews = new ConcurrentHashMap<>();
    private static final int MIN_WATCH_SECONDS_TO_COUNT = 30;

    public void recordPlayback(String videoId, int watchedSeconds) {
        if (watchedSeconds >= MIN_WATCH_SECONDS_TO_COUNT) {
            pendingViews.merge(videoId, 1, Integer::sum);
        }
    }

    public void flush(VideoDatabase db) {
        for (Map.Entry<String, Integer> entry : pendingViews.entrySet()) {
            db.incrementViewCount(entry.getKey(), entry.getValue());
        }
        pendingViews.clear();
    }

    public interface VideoDatabase {
        void incrementViewCount(String videoId, int amount);
    }
}

