// Buffers view increments in memory and flushes them to the database in
// batches, avoiding a write per individual view event on a viral video.
class ViewCountAggregator {
public:
    static constexpr int MIN_WATCH_SECONDS_TO_COUNT = 30;

    void recordPlayback(const std::string& videoId, int watchedSeconds) {
        if (watchedSeconds >= MIN_WATCH_SECONDS_TO_COUNT) pendingViews_[videoId]++;
    }
    void flush(VideoDatabase& db) {
        for (auto& [videoId, amount] : pendingViews_) db.incrementViewCount(videoId, amount);
        pendingViews_.clear();
    }

private:
    std::map<std::string, int> pendingViews_;
};

