    def record_playback(self, video_id: str, watched_seconds: int) -> None:
        if watched_seconds >= ViewCountAggregator.MIN_WATCH_SECONDS_TO_COUNT:
            self._pending_views[video_id] = self._pending_views.get(video_id, 0) + 1

    def flush(self, db: VideoDatabase) -> None:
        for video_id, amount in self._pending_views.items():
            db.increment_view_count(video_id, amount)
        self._pending_views.clear()

